-- XorWoW TCG: the card items, their drops and the card table the worldserver reads
-- (src/server/scripts/Custom/xorwow_tcg.cpp). GENERATED by scripts/client-patch/build_tcg.py
-- from client-patch/tcg/cards.json in the XorWoW repo: edit that and rebuild. Idempotent.
--
-- Card N is item 261000+N: a copy of the Hearthstone (class 15) that is not bound, stacks to 20
-- and is used up by its spell 261000 ("add to the collection", the Spell/Item.dbc rows come from
-- the client patch). Quality follows the tier: 1-2 white, 3-4 green, 5-6 blue, 7-8 purple, 9-10 orange.

CREATE TABLE IF NOT EXISTS `xorwow_tcg_card` (
    `id` TINYINT UNSIGNED NOT NULL,
    `name` VARCHAR(64) NOT NULL,
    `item` INT UNSIGNED NOT NULL,
    `creature` INT UNSIGNED NOT NULL,
    `tier` TINYINT UNSIGNED NOT NULL,
    `era` TINYINT UNSIGNED NOT NULL COMMENT '0 classic, 1 tbc, 2 wotlk: a card counts once its expansion is open',
    `top` TINYINT UNSIGNED NOT NULL,
    `right` TINYINT UNSIGNED NOT NULL,
    `bottom` TINYINT UNSIGNED NOT NULL,
    `left` TINYINT UNSIGNED NOT NULL,
    `element` TINYINT UNSIGNED NOT NULL COMMENT '0 none, 1 Water 2 Fire 3 Frost 4 Earth 5 Arcane 6 Holy 7 Shadow 8 Nature (the circle order)',
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `xorwow_tcg_card`;

DELETE FROM `item_template` WHERE `entry` BETWEEN 261001 AND 261999;
DELETE FROM `item_template_locale` WHERE `ID` BETWEEN 261001 AND 261999;
