DROP TEMPORARY TABLE `xorwow_tcg_item`;

-- the use spell: xorwow_tcg.cpp adds the card to the account (the item is used up by its charge)
DELETE FROM `spell_script_names` WHERE `spell_id` = 261000;

-- Drops: each card from its creature and the creature's heroic / 25-man versions. A creature
-- without loot (a chest boss like Malygos, a few elites) gets a loot table of its own.
DROP TEMPORARY TABLE IF EXISTS `xorwow_tcg_drop_base`;
DROP TEMPORARY TABLE IF EXISTS `xorwow_tcg_drop`;
CREATE TEMPORARY TABLE `xorwow_tcg_drop_base` (`creature` INT UNSIGNED NOT NULL, `item` INT UNSIGNED NOT NULL, `chance` FLOAT NOT NULL);
-- a temporary table can be named only once per query: the copies come from the base one
CREATE TEMPORARY TABLE `xorwow_tcg_drop` SELECT * FROM `xorwow_tcg_drop_base`;
UPDATE `creature_template` ct JOIN `xorwow_tcg_drop` d ON d.`creature` = ct.`entry` SET ct.`lootid` = ct.`entry` WHERE ct.`lootid` = 0;
DELETE FROM `creature_loot_template` WHERE `Item` BETWEEN 261001 AND 261999;
    SELECT DISTINCT ct.`lootid`, d.`item`, 0, d.`chance`, 0, 1, 0, 1, 1, 'XorWoW TCG card'
    FROM `xorwow_tcg_drop` d JOIN `creature_template` ct ON ct.`entry` = d.`creature` WHERE ct.`lootid` <> 0;
DROP TEMPORARY TABLE `xorwow_tcg_drop`;
DROP TEMPORARY TABLE `xorwow_tcg_drop_base`;
